import random, time, uuid

RETRYABLE = (TimeoutError, ConnectionError)

def charge_with_policy(call, deadline_s=5.0, per_try_s=1.0, base=0.1, cap=1.0, attempts=3, budget=None):
    """call(key, timeout) performs the POST; budget is a shared RetryBudget (ratio of retries to requests)."""
    key = str(uuid.uuid4())              # one key per logical operation, reused on every attempt
    start = time.monotonic()
    for attempt in range(attempts):
        remaining = deadline_s - (time.monotonic() - start)
        if remaining <= 0:
            raise TimeoutError("deadline exceeded before attempt %d" % (attempt + 1))
        try:
            return call(key, timeout=min(per_try_s, remaining))
        except RETRYABLE:
            last = attempt == attempts - 1
            if last or (budget is not None and not budget.allow_retry()):
                raise
            sleep = random.uniform(0, min(cap, base * 2 ** attempt))   # full jitter
            if sleep > deadline_s - (time.monotonic() - start):
                raise
            time.sleep(sleep)


class RetryBudget:
    """Allow a retry while retries stay under `ratio` of requests in the current window."""
    def __init__(self, ratio=0.1):
        self.ratio, self.requests, self.retries = ratio, 0, 0

    def record_request(self):
        self.requests += 1

    def allow_retry(self):
        if self.retries < self.ratio * max(self.requests, 1):
            self.retries += 1
            return True
        return False
